<div class="page-head"><div><span class="eyebrow dark"><?= e(tr('تحلیل درآمد','Revenue analytics')) ?></span><h1><?= e(tr('گزارش مالی','Financial report')) ?></h1><p><?= e(tr('مبالغ بر اساس پرداخت‌های ثبت‌شده محاسبه می‌شوند.','Figures are based on recorded payments.')) ?></p></div></div>
<section class="metric-grid three"><article class="metric-card green"><span class="metric-icon">●</span><div><small><?= e(tr('امروز','Today')) ?></small><strong class="money-value"><?= money($report['today']) ?></strong></div></article><article class="metric-card blue"><span class="metric-icon">◒</span><div><small><?= e(tr('این ماه','This month')) ?></small><strong class="money-value"><?= money($report['month']) ?></strong></div></article><article class="metric-card violet"><span class="metric-icon">↗</span><div><small><?= e(tr('این سال','This year')) ?></small><strong class="money-value"><?= money($report['year']) ?></strong></div></article></section>
<section class="panel"><div class="panel-head"><div><h2><?= e(tr('فاکتورهای سررسید گذشته','Overdue invoices')) ?></h2><p><?= fa_digits(count($overdue)) ?> <?= e(tr('مورد نیازمند پیگیری','items need attention')) ?></p></div></div><div class="table-wrap"><table><thead><tr><th><?= e(tr('شماره','Number')) ?></th><th><?= e(tr('کاربر','User')) ?></th><th><?= e(tr('سررسید','Due')) ?></th><th><?= e(tr('مبلغ','Total')) ?></th><th><?= e(tr('مانده','Balance')) ?></th></tr></thead><tbody><?php foreach($overdue as $item):?><tr><td><a href="<?= e(url('invoice-detail',['id'=>$item['id']])) ?>" dir="ltr"><?= e($item['invoice_number']) ?></a></td><td dir="ltr"><?= e($item['username']) ?></td><td class="danger-text"><?= e($item['due_date']) ?></td><td><?= money($item['total'],$item['currency']?:'IRR') ?></td><td><?= money(max(0,$item['total']-$item['paid_amount']),$item['currency']?:'IRR') ?></td></tr><?php endforeach;?><?php if(!$overdue):?><tr><td colspan="5" class="empty success-text"><?= e(tr('فاکتور معوقی وجود ندارد.','There are no overdue invoices.')) ?></td></tr><?php endif;?></tbody></table></div></section>

